def transform(grid):
    g = [row[:] for row in grid]
    if not g:
        return g
    # The matching endpoint color appears in the top and bottom rows;
    # the full-width 2 line marks where the vertical fill stops.
    top = 0
    bottom = len(g) - 1
    color = next((v for v in g[top] if v != 0), None)
    if color is None:
        return g
    top_cols = {c for c, v in enumerate(g[top]) if v == color}
    bottom_cols = {c for c, v in enumerate(g[bottom]) if v == color}
    shared = top_cols & bottom_cols
    separator = next((r for r in range(top + 1, bottom)
                      if all(v == 2 for v in g[r])), None)
    if separator is None:
        return g
    for c in shared:
        for r in range(top + 1, separator):
            if g[r][c] == 0:
                g[r][c] = 4
    return g
